/bin/bash -c "python3 - <<'PY'
from fractions import Fraction as F

def row(w1,w2,p,q):
    if abs(p-q)<1e-13: return 0.
    if p<q:
        return min(w2*(q-p)/(1-p),w1*(q-p)/q)
    return min(w1*(p-q)/(1-q),w2*(p-q)/p)
def pair(tl,tr):
    nl=(7*tl-2)/3
    nr=3*tr/7
    u=row(.35,.15,tl,tr)+row(.15,.35,nl,nr)
    e=.7*tl+.3*tr-.1
    return u,e
betas=[.4,.5,.59,.6,.61,.7,.9]
best={b:(float('inf'),None) for b in betas}
best_constrained=(float('inf'),None)
best_chord=(float('inf'),None)
n=700
for i in range(n+1):
    tl=2/7+(3/7)*(i/n)
    for j in range(n+1):
        tr=j/n
        u,e=pair(tl,tr)
        if e<=.2+1e-12 and u<best_constrained[0]: best_constrained=(u,(e,tl,tr))
        v=.6*u+.4*e
        if v<best_chord[0]: best_chord=(v,(u,e,tl,tr))
        for beta in betas:
            v=beta*u+(1-beta)*e
            if v<best[beta][0]: best[beta]=(v,(u,e,tl,tr))
print('Feasible point at error cap .2:',pair(.3,.3))
print('Grid constrained minimum:',best_constrained)
print('Grid minimum at beta .6:',best_chord)
print('Weighted sum solutions:',best)
print('Exact endpoints:',pair(2/7,0),pair(.35,.35),pair(2/7,2/7))
PY"
